/**
 * Utility to safely retrieve the first item from a specific node
 */
function getFirstItem(nodeName) {
  try {
    const arr = $(nodeName).all();
    if (!arr || !Array.isArray(arr) || arr.length === 0) return null;
    return arr[0];
  } catch (e) {
    return null;
  }
}

/**
 * Utility to handle content that might be JSON or Plain Text
 */
function smartParse(rawContent, typeLabel) {
  if (!rawContent) return null;

  // If it's already an object, return it
  if (typeof rawContent === 'object') return rawContent;

  try {
    // Attempt to clean the string if it contains markdown blocks
    const cleanJson = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanJson);
  } catch (e) {
    // Fallback: If it's not JSON, treat it as structured text for the PDF/Binary conversion
    return {
      type: "structured_text",
      title: typeLabel,
      content: rawContent.trim()
    };
  }
}

// 1. Extract Summary
// Checking all possible paths including the State Manager's output
const stateManagerItem = getFirstItem('State Manager');
const validatedSummaryItem = getFirstItem('Save Validated Summary');
const rawSummarizerItem = getFirstItem('Summarizer');

const summary = validatedSummaryItem?.json?.summary 
             || stateManagerItem?.json?.summarizer_agent_output
             || rawSummarizerItem?.json?.output 
             || rawSummarizerItem?.json?.text 
             || "No summary was generated.";

// 2. Extract Quiz output
const quizItem = getFirstItem('Quiz Agent');
const quizRaw = quizItem?.json?.output || quizItem?.json?.text;

// 3. Extract Flashcard output
const flashItem = getFirstItem('Flashcard Agent');
const flashRaw = flashItem?.json?.output || flashItem?.json?.text;

// 4. Process outputs using Smart Parse
const quiz = smartParse(quizRaw, "Quiz");
const flashcards = smartParse(flashRaw, "Flashcards");

return [
  {
    json: {
      summary: summary,
      quiz: quiz,
      flashcards: flashcards,
      metadata: {
        summary_source: validatedSummaryItem ? 'validated' : (rawSummarizerItem ? 'raw' : 'state'),
        has_content: !!(summary !== "No summary was generated." || quiz || flashcards),
        generated_at: new Date().toISOString()
      }
    },
  },
];

