/**
 * Smart Aggregator: Prepares the payload and handles the 'trigger_judge' logic.
 * Uses string literals for node access to ensure n8n optimization.
 */

// 1. Initialize the storage for results
let aggregatedData = {
  source_chunks: "",
  summarizer_agent_output: null,
  quiz_agent_output: null,
  flashcard_agent_output: null,
  sate_extractor_output: null,
  trigger_judge: false
};

// Track how many agents successfully returned data
let completedCount = 0;
const totalRequired = 2; // Total number of agents we are waiting for

// 2. Extract inputs safely using string literals
try {
  const node = $('Summarizer Agent').first();
  if (node && node.json) {
    aggregatedData.summarizer_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Quiz Agent').first();
  if (node && node.json) {
    aggregatedData.quiz_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Flashcard Agent').first();
  if (node && node.json) {
    aggregatedData.flashcard_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Sate Extractor').first();
  if (node && node.json) {
    aggregatedData.sate_extractor_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

// Extract source content (usually doesn't count towards the agent completion total)
try {
  aggregatedData.source_chunks = $('RAG Knowledge Base (Insert)').first().json.pageContent || "";
} catch (e) {
  aggregatedData.source_chunks = "Source content unavailable";
}

// 3. Final Logic: Trigger Judge only if all required tasks are done
if (completedCount === totalRequired) {
  aggregatedData.trigger_judge = true;
}

// 4. Return the aggregated data for the following IF node
return [{
  json: aggregatedData
}];

/**
 * n8n Code Node (JavaScript)
 * Logic: Data-Driven State Management
 * This version determines status by checking if actual content exists.
 */

const items = $input.all();
if (items.length === 0) return []; 

const input_data = items[0].json;

// 1. HELPER: Check if content is valid/non-empty
const hasContent = (data) => {
    if (!data) return false;
    if (typeof data === 'string' && data.trim().length > 0) return true;
    if (Array.isArray(data) && data.length > 0) return true;
    if (typeof data === 'object' && Object.keys(data).length > 0) return true;
    return false;
};

// 2. EXTRACT PREFERENCES
const prefs = input_data.user_preferences || { "summary": true, "quiz": false, "flashcards": false };

// 3. DETERMINE STATUS BASED ON DATA PRESENCE (The "Cumulative" Logic)
// If content exists, it's DONE. Otherwise, check if it's even requested (PENDING vs SKIPPED)
let current_summary = hasContent($input.first().json.summarizer_agent_output) ? "DONE" : (prefs.summary ? "PENDING" : "SKIPPED");
let current_quiz = hasContent($input.first().json.quiz_agent_output) ? "DONE" : (prefs.quiz ? "PENDING" : "SKIPPED");
let current_flashcards = hasContent($input.first().json.flashcard_agent_output) ? "DONE" : (prefs.flashcards ? "PENDING" : "SKIPPED");

let latest_feedback = input_data.latest_feedback || "";
let pack_approved = input_data.pack_approved || false;

// 4. JUDGE OVERRIDE (Revisions)
// Adjusted logic to specifically look for "APPROVED" or "REVISE" strings
// 4. JUDGE OVERRIDE (Authoritative)
try {
  let judge_data = null;

  try {
    const judgeNode = $('Judge Agent').first().json;
    judge_data = judgeNode.output || judgeNode;
  } catch (e) {}

  if (typeof judge_data === "string") {
    try {
      judge_data = JSON.parse(judge_data);
    } catch (e) {
      judge_data = null;
    }
  }

  if (judge_data && judge_data.decisions) {
    const d = judge_data.decisions;

    if (d.summary === "APPROVED") current_summary = "APPROVED";
    if (d.quiz === "APPROVED") current_quiz = "APPROVED";
    if (d.flashcards === "APPROVED") current_flashcards = "APPROVED";

    if (d.summary === "REVISE") current_summary = "PENDING";
    if (d.quiz === "REVISE") current_quiz = "PENDING";
    if (d.flashcards === "REVISE") current_flashcards = "PENDING";

    if (
      (d.summary === "APPROVED" || d.summary === "SKIPPED") &&
      (d.quiz === "APPROVED" || d.quiz === "SKIPPED") &&
      (d.flashcards === "APPROVED" || d.flashcards === "SKIPPED")
    ) {
      pack_approved = true;
    }

    if (judge_data.revision_instructions) {
      latest_feedback =
        typeof judge_data.revision_instructions === "string"
          ? judge_data.revision_instructions
          : JSON.stringify(judge_data.revision_instructions);
    }
  }
} catch (e) {}



// 5. FINAL STATE CONSTRUCTION
const new_state = {
    // ...input_data, // Maintains summary_text, quiz_data, etc.
    // summary_status: current_summary,
    // quiz_status: current_quiz,
    // flashcard_status: current_flashcards,
    // pack_approved: pack_approved,
    // latest_feedback: latest_feedback,
    // last_sync: new Date().toISOString()
    summary_status: current_summary,
    quiz_status: current_quiz,
    flashcard_status: current_flashcards,
    pack_approved: pack_approved,
    latest_feedback: latest_feedback,
    last_sync: new Date().toISOString(),

    // carry forward immutable data only
    pageContent: input_data.pageContent,
    user_preferences: input_data.user_preferences
};

return [{ json: new_state }];

const outputItems = [];

for (const item of $input.all()) {
  const incomingData = item.json || {};
  const rawOutput = incomingData.output || '';

  let nextStep = "FINALIZE"; // Default next step
  let reasoning = "No reasoning provided"; // Default reasoning
  let instructionsForWorker = ""; // Default instructions
  let iterationCount = 0;
  let parseError = false;

  try {
    if (rawOutput) {
      let cleanedOutput = rawOutput.trim();

      // Remove Markdown Code Blocks (if they exist)
      if (cleanedOutput.startsWith("```")) {
        const lines = cleanedOutput.split('\n');
        if (lines[0].toLowerCase().includes("json") || lines[0] === "```") {
          cleanedOutput = lines.slice(1, -1).join('\n').trim();
        }
      }

      // Fix invalid backslash escapes
      cleanedOutput = cleanedOutput.replace(/\\(?![/"\\bfnrt]|u[0-9a-fA-F]{4})/g, '');

      const data = JSON.parse(cleanedOutput);

      // Extract next_step value and normalize the case to upper
      if (data.next_step !== undefined) {
        if (typeof data.next_step === 'object' && data.next_step.enum && Array.isArray(data.next_step.enum)) {
          nextStep = data.next_step.enum[0].toUpperCase(); // Convert to uppercase for consistency
        } else {
          nextStep = data.next_step.toUpperCase(); // Convert to uppercase for consistency
        }
      }

      // Extract reasoning, if available
      if (data.reasoning !== undefined) {
        if (typeof data.reasoning === 'object' && data.reasoning.description) {
          reasoning = data.reasoning.description;
        } else {
          reasoning = data.reasoning;
        }
      }

      // Extract iteration count if available
      if (data.iteration_count !== undefined) {
        if (typeof data.iteration_count === 'object' && data.iteration_count.description) {
          iterationCount = parseInt(data.iteration_count.description);
        } else {
          iterationCount = data.iteration_count;
        }
      }

      // Set instructions_for_worker if relevant feedback exists
      if (data.latest_feedback && (nextStep === "SUMMARIZER" || nextStep === "QUIZ_GEN" || nextStep === "FLASHCARD_GEN")) {
        instructionsForWorker = data.latest_feedback;
      }
    } else {
      reasoning = "Input 'output' field was empty.";
    }
  } catch (e) {
    reasoning = `PARSE ERROR: ${e.message}`;
    parseError = true;
  }

  // Construct the final output
  outputItems.push({
    json: {
      next_step: nextStep,
      reasoning: reasoning,
      instructions_for_worker: instructionsForWorker,
      pageContent: incomingData.pageContent || "", // Ensure pageContent is passed through correctly
      iteration_count: iterationCount,
      is_debug_error: parseError,
      original_agent_response: rawOutput
    }
  });
}

return outputItems;

/**
 * n8n Code Node (JavaScript)
 * Logic: Data-Driven State Management
 * This version handles user feedback and routes it to the appropriate agents.
 * Additionally, it integrates feedback for the Judge Agent.
 */

const items = $input.all();
if (items.length === 0) return []; 

const input_data = items[0].json;

// 1. HELPER: Check if content is valid/non-empty
const hasContent = (data) => {
    if (!data) return false;
    if (typeof data === 'string' && data.trim().length > 0) return true;
    if (Array.isArray(data) && data.length > 0) return true;
    if (typeof data === 'object' && Object.keys(data).length > 0) return true;
    return false;
};

// 2. EXTRACT PREFERENCES
const prefs = input_data.user_preferences || { "summary": true, "quiz": true, "flashcards": true };

// 3. DETERMINE STATUS BASED ON DATA PRESENCE (The "Cumulative" Logic)
// If content exists, it's DONE. Otherwise, check if it's even requested (PENDING vs SKIPPED)
let current_summary = hasContent($input.first().json.summarizer_agent_output) ? "DONE" : (prefs.summary ? "PENDING" : "SKIPPED");
let current_quiz = hasContent($input.first().json.quiz_agent_output) ? "DONE" : (prefs.quiz ? "PENDING" : "SKIPPED");
let current_flashcards = hasContent($input.first().json.flashcard_agent_output) ? "DONE" : (prefs.flashcards ? "PENDING" : "SKIPPED");

let latest_feedback_text = input_data.latest_feedback || "";  // This is the user feedback (whole text)
let pack_approved = input_data.pack_approved || false;

// 4. JUDGE OVERRIDE (Revisions)
// Adjusted logic to specifically look for "APPROVED" or "REVISE" strings
try {
  let judge_data = null;

  try {
    const judgeNode = $('Judge Agent').first().json;
    judge_data = judgeNode.output || judgeNode;
  } catch (e) {}

  if (typeof judge_data === "string") {
    try {
      judge_data = JSON.parse(judge_data);
    } catch (e) {
      judge_data = null;
    }
  }

  if (judge_data && judge_data.decisions) {
    const d = judge_data.decisions;

    if (d.summary === "APPROVED") current_summary = "APPROVED";
    if (d.quiz === "APPROVED") current_quiz = "APPROVED";
    if (d.flashcards === "APPROVED") current_flashcards = "APPROVED";

    if (d.summary === "REVISE") current_summary = "PENDING";
    if (d.quiz === "REVISE") current_quiz = "PENDING";
    if (d.flashcards === "REVISE") current_flashcards = "PENDING";

    if (
      (d.summary === "APPROVED" || d.summary === "SKIPPED") &&
      (d.quiz === "APPROVED" || d.quiz === "SKIPPED") &&
      (d.flashcards === "APPROVED" || d.flashcards === "SKIPPED")
    ) {
      pack_approved = true;
    }

    if (judge_data.revision_instructions) {
      latest_feedback_text =
        typeof judge_data.revision_instructions === "string"
          ? judge_data.revision_instructions
          : JSON.stringify(judge_data.revision_instructions);
    }
  }
} catch (e) {}

// 5. HANDLE USER FEEDBACK FROM CHATBOT (No Tokenization, just one line)
let feedback_tokens = {
  summary: "",
  quiz: "",
  flashcards: ""
};

// 6. UPDATE PREFERENCES BASED ON USER FEEDBACK
if (latest_feedback_text) {
  const feedback = latest_feedback_text.toLowerCase();

  if (feedback.includes("summary")) {
    prefs.summary = true;  // Enable summary processing
    feedback_tokens.summary = latest_feedback_text;  // Full feedback text for summary
  } else {
    prefs.summary = false; // Disable summary if no feedback
  }

  if (feedback.includes("quiz")) {
    prefs.quiz = true;  // Enable quiz processing
    feedback_tokens.quiz = latest_feedback_text;  // Full feedback text for quiz
  } else {
    prefs.quiz = false; // Disable quiz if no feedback
  }

  if (feedback.includes("flashcard")) {
    prefs.flashcards = true;  // Enable flashcard processing
    feedback_tokens.flashcards = latest_feedback_text;  // Full feedback text for flashcards
  } else {
    prefs.flashcards = false; // Disable flashcards if no feedback
  }
}

// 7. FINAL STATE CONSTRUCTION
const new_state = {
    summary_status: current_summary,
    summary_user_feedback: feedback_tokens.summary || null,

    quiz_status: current_quiz,
    quiz_user_feedback: feedback_tokens.quiz || null,

    flashcard_status: current_flashcards,
    flashcards_user_feedback: feedback_tokens.flashcards || null,

    pack_approved: pack_approved,
    latest_feedback: latest_feedback_text,
    last_sync: new Date().toISOString(),

    // Carry forward immutable data only
    pageContent: input_data.pageContent,
    user_preferences: prefs
};

// 8. RETURN OUTPUT WITH USER FEEDBACK FOR AGENTS
// Pass the feedback and agent statuses to be used in the workflow for further revisions by agents
return [{
  json: {
    ...new_state,
    summary_user_feedback: feedback_tokens.summary,
    quiz_user_feedback: feedback_tokens.quiz,
    flashcards_user_feedback: feedback_tokens.flashcards
  }
}];
